args<-commandArgs(trailingOnly=TRUE);root<-args[1]
suppressPackageStartupMessages(library(ggplot2))
dir.create(file.path(root,'figures'),showWarnings=FALSE)
theme_set(theme_bw(base_size=11)+theme(panel.grid.minor=element_blank(),legend.position='bottom',plot.title=element_text(face='bold'),plot.subtitle=element_text(size=10),strip.background=element_rect(fill='#EBF0F3')))
cols<-c(nonlinear='#167D9A',linear='#D97732',oracle='#7158A5')
savefig<-function(name,p,w=8,h=5){ggsave(file.path(root,'figures',paste0(name,'.png')),p,width=w,height=h,dpi=300,bg='white');ggsave(file.path(root,'figures',paste0(name,'.pdf')),p,width=w,height=h,device=cairo_pdf)}
w<-read.csv(file.path(root,'data/weather.csv'));w$site_name<-gsub('_',' ',w$site_name);w$month<-as.Date(paste0(substr(w$date,1,7),'-01'));monthly<-aggregate(tmax_c~site_name+month,w,mean)
savefig('weather',ggplot(monthly,aes(month,tmax_c))+geom_line(colour='#167D9A',linewidth=.5)+facet_wrap(~site_name,ncol=3)+labs(x=NULL,y='Monthly mean daily maximum temperature (deg C)',title='Public ERA5 weather across six illustrative locations',subtitle='2019-2024 reanalysis weather; no participant observations'),8,4.6)
d<-read.csv(file.path(root,'results/response_curve.csv'))
savefig('response',ggplot(d,aes(temperature,ratio))+geom_ribbon(aes(ymin=lower,ymax=upper),fill='#B7D9E4',alpha=.6)+geom_line(colour='#167D9A',linewidth=.9)+geom_line(aes(y=truth),colour='#B45D29',linetype=2,linewidth=.8)+geom_hline(yintercept=1,linetype=3)+labs(x='Temperature in each completed lag window (deg C)',y='Interval cumulative hazard ratio',title='Recovery of the simulated joint heat response',subtitle='Blue: fitted model and pointwise 95% CI; dashed: generating truth'),7.5,4.7)
s<-read.csv(file.path(root,'results/simulation_summary.csv'));s$scenario<-factor(s$scenario,levels=c('null','moderate','nonlinear','exposure_error','informative_missingness'),labels=c('Null','Moderate','Nonlinear','Exposure error','Informative missingness'))
savefig('simulation_bias',ggplot(s,aes(bias,scenario,colour=model))+geom_vline(xintercept=0,linetype=2,colour='grey50')+geom_errorbar(aes(xmin=bias-1.96*bias_mcse,xmax=bias+1.96*bias_mcse),orientation='y',position=position_dodge(width=.6),width=.2)+geom_point(position=position_dodge(width=.6),size=2)+scale_colour_manual(values=cols)+labs(x='Bias in log joint heat contrast',y=NULL,colour='Model',title='Bias across 100 replicates per scenario',subtitle='Bars show Monte Carlo uncertainty in average bias'),8,4.5)
long<-rbind(data.frame(s[,c('scenario','model')],metric='95% interval coverage',value=s$coverage,se=s$coverage_mcse),data.frame(s[,c('scenario','model')],metric='Rejection at 5%',value=s$rejection_rate,se=s$rejection_mcse))
den<-1+1.96^2/100;center<-(long$value+1.96^2/200)/den;half<-1.96*sqrt(long$value*(1-long$value)/100+1.96^2/(4*100^2))/den;long$lo<-center-half;long$hi<-center+half
savefig('simulation_calibration',ggplot(long,aes(scenario,value,colour=model))+geom_point(position=position_dodge(width=.6),size=2)+geom_errorbar(aes(ymin=lo,ymax=hi),position=position_dodge(width=.6),width=.15)+facet_wrap(~metric,ncol=1)+scale_colour_manual(values=cols)+coord_cartesian(ylim=c(0,1))+theme(axis.text.x=element_text(size=9))+labs(x=NULL,y='Proportion of replicates',colour='Model',title='Calibration and rejection under known simulated truth',subtitle='Wilson 95% intervals; rejection is type I error only in the null scenario'),8,6)
roc<-read.csv(file.path(root,'results/r_roc.csv'));roc$test<-factor(roc$test,levels=c('temporal','geographic','combined_shift'),labels=c('Temporal test','Geographic test','Combined shift'))
savefig('roc',ggplot(roc,aes(fpr,tpr,colour=model))+geom_abline(slope=1,intercept=0,linetype=2,colour='grey60')+geom_path(linewidth=.7)+facet_wrap(~test,ncol=3)+coord_equal()+labs(x='False positive rate',y='Sensitivity',colour='R model',title='Held out prediction at the week 28 landmark',subtitle='Synthetic pregnancies; only weather available at the landmark is used'),9,4.2)
cal<-read.csv(file.path(root,'results/r_calibration.csv'));cal$test<-factor(cal$test,levels=c('temporal','geographic','combined_shift'),labels=c('Temporal test','Geographic test','Combined shift'))
savefig('prediction_calibration',ggplot(cal,aes(mean_prediction,observed,colour=model))+geom_abline(slope=1,intercept=0,linetype=2,colour='grey60')+geom_line()+geom_point(aes(size=n))+facet_wrap(~test,ncol=3)+coord_equal(xlim=c(0,.35),ylim=c(0,.35))+labs(x='Mean predicted probability',y='Observed preterm proportion',colour='R model',size='Participants',title='Calibration on held out synthetic pregnancies',subtitle='Five probability groups per model and test set; these are descriptive bins'),9,4.2)
